package com.univmar.customer.api;
import com.univmar.common.api.*; import com.univmar.customer.CustomerService; import com.univmar.customer.api.CustomerDtos.*; import com.univmar.customer.domain.CustomerType; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.data.domain.Pageable; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/customers") public class CustomerController { private final CustomerService customers; public CustomerController(CustomerService customers){this.customers=customers;} @GetMapping public ApiResponse<CustomerPage> list(@RequestParam(required=false)String search,@RequestParam(required=false)CustomerType type,@RequestParam(required=false)Boolean active,@PageableDefault(size=20,sort="name")Pageable pageable,HttpServletRequest request){return ok(customers.list(search,type,active,pageable),request);} @PostMapping public ResponseEntity<ApiResponse<CustomerResponse>> create(@Valid @RequestBody CustomerInput input,HttpServletRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(ok(customers.create(input),request));} @GetMapping("/{id}") public ApiResponse<CustomerResponse> detail(@PathVariable UUID id,HttpServletRequest request){return ok(customers.detail(id),request);} @PutMapping("/{id}") public ApiResponse<CustomerResponse> update(@PathVariable UUID id,@Valid @RequestBody CustomerInput input,HttpServletRequest request){return ok(customers.update(id,input),request);} @PostMapping("/{id}/contacts") public ApiResponse<CustomerResponse> contact(@PathVariable UUID id,@Valid @RequestBody ContactInput input,HttpServletRequest request){return ok(customers.addContact(id,input),request);} @PostMapping("/{id}/addresses") public ApiResponse<CustomerResponse> address(@PathVariable UUID id,@Valid @RequestBody AddressInput input,HttpServletRequest request){return ok(customers.addAddress(id,input),request);} private <T> ApiResponse<T> ok(T data,HttpServletRequest request){return ApiResponse.of(data,(String)request.getAttribute(RequestIdFilter.REQUEST_ID_ATTRIBUTE));} }
